use svmvisor_hypervisor::svm::{native_diagnostic_config::{prepare_io,ConfigError},vmcb::Vmcb};
fn put(v:&mut Vmcb,o:usize,x:u64){unsafe{core::ptr::copy_nonoverlapping(x.to_le_bytes().as_ptr(),(v as *mut Vmcb).cast::<u8>().add(o),8)}}
fn stopped(port:u16,size:u8,input:bool)->Vmcb{let mut v=Vmcb::new();for(o,x)in[(0x70,0x7b),(0x78,(u64::from(port)<<16)|(u64::from(size)<<4)|u64::from(input)),(0x80,0x2002),(0xc8,0xdead),(0x410,0x29bu64<<16),(0x4d0,0x1500),(0x558,0x80000001),(0x548,0x20),(0x550,0x1000),(0x578,0x2000),(0x570,0x10002),(0x5f8,0xaabbccddeeff1122)]{put(&mut v,o,x)}v}
#[test]fn configuration_data_writes_revoke_before_hardware_and_reads_preserve_width(){for(port,width)in[(0xcf8,4),(0xcfc,1),(0xcfd,1),(0xcfe,2),(0xcfc,4)]{for input in[false,true]{let mut v=stopped(port,width,input);let p=prepare_io(&mut v).unwrap();assert_eq!(p.revoke(),!input&&port!=0xcf8);assert_eq!(p.port(),port);assert_eq!(p.width_bytes(),width);p.commit(0x87654321);assert_eq!(v.guest_rip(),0x2002);assert_eq!(v.guest_rax(),if !input{0xaabbccddeeff1122}else{match width{1=>0xaabbccddeeff1121,2=>0xaabbccddeeff4321,_=>0x87654321}});}}}
#[test]fn every_configuration_data_lane_revokes_without_selector_or_bdf_assumptions(){
for port in 0xcfc..=0xcff {let mut v=stopped(port,1,false);assert!(prepare_io(&mut v).unwrap().revoke());}}

#[test]fn malformed_or_unsupported_never_changes_stopped_state(){for(port,width)in[(0xcf8,1),(0xcf9,4),(0xcfa,2),(0xcfd,2),(0xcfe,4),(0xcff,2),(0xd00,4)]{let mut v=stopped(port,width,false);let before=*v.bytes();assert!(matches!(prepare_io(&mut v),Err(ConfigError::PortOrWidth)));assert_eq!(*v.bytes(),before);}for(o,x)in[(0x78,(0xcfcu64<<16)|0x44),(0x80,0x2000),(0x80,0x2010),(0x570,0x102),(0x4c8,3u64<<24)]{let mut v=stopped(0xcfc,4,false);put(&mut v,o,x);let before=*v.bytes();assert!(prepare_io(&mut v).is_err());assert_eq!(*v.bytes(),before);}}
#[test]fn dropping_prepared_transaction_has_no_side_effect(){let mut v=stopped(0xcfc,4,false);let before=*v.bytes();drop(prepare_io(&mut v).unwrap());assert_eq!(*v.bytes(),before);}
